-- =========================================================================
-- Helper: server-side random sampler RPC (returns N random active questions)
-- Used by /api/quiz/questions so every attempt gets a different set.
-- =========================================================================
create or replace function sample_quiz_questions(p_count int default 20)
returns setof quiz_questions
language sql
security definer
set search_path = public
stable
as $$
  select * from quiz_questions
  where active = true
  order by random()
  limit greatest(1, least(p_count, 50));
$$;

grant execute on function sample_quiz_questions(int) to anon, authenticated;
